source.jsLib:
// jmLib: 线路/模式/请求工具（规则 @js 与 loginUrl 共享；ES5 语法，Rhino 安全子集）
var JM_HOST_DEF = 'https://abandon.yyc2mhau.cc';
var JM_UA = 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.6367.82 Mobile Safari/537.36';
var JM_PUB = 'https://jmtt1.net';

function jmStr(v) {
  var s = String(v == null ? '' : v);
  if (s === 'null' || s === 'undefined') s = '';
  return s;
}

function jmHost(sv) {
  try {
    var h = jmStr(sv.get('jmHost'));
    if (h.indexOf('http') === 0) return h;
  } catch (e1) {}
  try {
    var v = jmStr(sv.getVariable());
    if (v.indexOf('http') === 0) return v;
  } catch (e2) {}
  return JM_HOST_DEF;
}

function jmUA() {
  return JM_UA;
}

function jmOpt(timeout) {
  var t = timeout || 20000;
  return ',{"headers":{"User-Agent":"' + JM_UA + '"},"timeout":' + t + '}';
}

function jmMode(sv) {
  var m = '';
  try {
    m = jmStr(sv.get('jmMode'));
  } catch (e1) {}
  if (m === '') {
    try {
      var v = sv.getVariable();
      m = jmStr(v);
    } catch (e2) {}
  }
  if (m === '小说' || m === '视频') return m;
  return '漫画';
}

source.loginUrl:
// jmtt loginUrl: 登录检查 + 三模式切换 + 发布页获取线路 + 测速选线（V1 静态 loginUi 的 action 函数库）
// 环境：$loginJS\n$buttonJS，source/java 绑定可用；java=SourceLoginJsExtensions（put/get/toast/longToast/ajax）
// ★ 本串中 Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.6367.82 Mobile Safari/537.36 占位在构建时替换为真实 UA；单引号字符串，避免与 action 的 Q() 拼接冲突
function login() {
  return '游客模式可用，无需登录。请使用下方按钮管理线路与模式。';
}

function jmQ(c) {
  return String.fromCharCode(39);
}

function jmToast(jv, msg) {
  try { jv.toast(msg); } catch (e1) {}
  try { jv.longToast(msg); } catch (e2) {}
}
// 三模式切换：source.put('jmMode', mode) + 刷新面板按钮名
function jmSetMode(java, mode) {
  var jv = java;
  try { jv.put('jmMode', mode); } catch (e1) {}
  try { jv.setVariable(mode); } catch (e1b) {}
  try { jv.toast('已切换：' + mode + ' 模式'); } catch (e2) {}
  try { jv.reLoginView(false); } catch (e3) {}
  return mode;
}

// 一键从发布页获取线路：抓 jmtt1.net 词表 → 生成候选 → 并发测速 → 最快者写 jmHost
function jmFetchLines(java) {
  var jv = java;
  var msg = '';
  try {
    jmToast(jv, '⏳ 正在从发布页 jmtt1.net 获取线路…');
    var pub = String(jv.ajax(jmPubUrl() + ',{"timeout":15000}'));
    var mw = pub.match(/words\s*=\s*'([a-z,]+)'/);
    if (!mw) { jmToast(jv, '❌ 发布页词表解析失败（检查发布页地址）'); return; }
    var words = mw[1].split(',');
    msg = '词表 ' + words.length + ' 词；';
    // 生成候选：词表随机取 4 + backup 固定 2 = 6 线（与面板 6 个线路按钮对应）
    var cand = [];
    var used = {};
    var tries = 0;
    while (cand.length < 4 && tries < 60) {
      tries++;
      var w = words[Math.floor(Math.random() * words.length)];
      if (w && !used[w]) { used[w] = 1; cand.push('https://' + w + '.yyc2mhau.cc'); }
    }
    // backup 固定域（/index/backup 页实测域名池样本）
    var fixed = ['https://w9xfv.yyc2mhau.cc', 'https://18mh.01buliangrukou.com'];
    for (var fi = 0; fi < fixed.length; fi++) {
      if (cand.indexOf(fixed[fi]) < 0) cand.push(fixed[fi]);
    }
    jmSpeedTest(java, cand);
  } catch (e) {
    jmToast(jv, '❌ 获取线路失败：' + String(e).substring(0, 120));
  }
}
// 逐线路测速：结果写 jmLatN 供 viewName 显示，最快写 jmHost；含 4073ms 防抖守卫
function jmSpeedTest(java, cand) {
  var jv = java;
  var best = -1;
  var bestMs = 999999;
  for (var i = 0; i < cand.length; i++) {
    var u = cand[i];
    var t0 = Date.now();
    var ok = false;
    try {
      String(jv.ajax(u + '/favicon.ico,{"timeout":8000}'));
      ok = true;
    } catch (e) { ok = false; }
    var ms = Date.now() - t0;
    if (!ok) ms = 999999;
    try { jv.put('jmLat' + i, ok ? (ms + 'ms') : '超时'); } catch (ep) {}
    try { jv.put('jmLine' + i, u); } catch (ep2) {}
    if (ok && ms < bestMs) { bestMs = ms; best = i; }
  }
  var msg = '';
  for (var j = 0; j < cand.length; j++) {
    var l = '';
    try { l = jmStr(jv.get('jmLine' + j)); } catch (eg) {}
    var lt = '';
    try { lt = jmStr(jv.get('jmLat' + j)); } catch (eg2) {}
    if (l !== '') msg += (j + 1) + '. ' + l.replace('https://', '') + ' → ' + lt + '\n';
  }
  var cur = '';
  try { cur = jmStr(jv.get('jmHost')); } catch (eg3) {}
  if (best >= 0) {
    try { jv.put('jmHost', cand[best]); } catch (ep3) {}
    msg += '✅ 已切换最快线路：' + cand[best].replace('https://', '') + '（' + bestMs + 'ms）';
    jmToast(jv, msg);
  } else {
    msg += '❌ 全部线路不可达';
    jmToast(jv, msg);
  }
  try { jv.reLoginView(false); } catch (er) {}
}

// 保存发布页输入值；jmGetPubInp 始终返回 true（V1 静态面板 text 行的值经 form 机制自动持久化）
function jmSavePub(java) {
  var jv = java;
  var v = '';
  try { v = jmStr(jv.get('jmPub')); } catch (e) {}
  if (v.indexOf('http') !== 0) v = 'https://jmtt1.net';
  try { jv.put('jmPub', v); } catch (e2) {}
  jmToast(jv, '✅ 发布页地址已保存：' + v);
  try { jv.reLoginView(false); } catch (e3) {}
}

function jmGetPubInp(v) {
  return true;
}

// jmFetchLines 改从 jmPub 读发布页地址
function jmPubUrl() {
  var v = '';
  try { v = jmStr(source.get('jmPub')); } catch (e) {}
  if (v.indexOf('http') !== 0) v = 'https://jmtt1.net';
  return v.replace(/\/+$/, '');
}

// —— loginUrl 作用域独立的工具副本（不依赖 jsLib）——
function jmStr(v) {
  var s = String(v == null ? '' : v);
  if (s === 'null' || s === 'undefined') s = '';
  return s;
}

// 测试当前已存线路延时（不自动切换，只回填 ms 到各按钮）
function jmTestCurrent(java) {
  var jv = java;
  var cand = [];
  for (var i = 0; i < 6; i++) {
    var u = '';
    try { u = jmStr(jv.get('jmLine' + i)); } catch (e) {}
    if (u.indexOf('http') === 0) cand.push(u);
  }
  if (cand.length === 0) {
    jmToast(jv, '⚠️ 尚无线路缓存，请先点「📡 从发布页获取线路」');
    return;
  }
  jmSpeedTest(java, cand, false);
}

// 点击某个线路按钮：快测该线 → 可达则切换 jmHost
function jmPickLine(java, idx) {
  var jv = java;
  var u = '';
  try { u = jmStr(jv.get('jmLine' + idx)); } catch (e) {}
  if (u.indexOf('http') !== 0) {
    jmToast(jv, '⚠️ 该线路位为空，请先点「📡 从发布页获取线路」');
    return;
  }
  jmToast(jv, '⏳ 正在测试 ' + u.replace('https://', '') + ' …');
  var t0 = Date.now();
  var ok = false;
  try {
    String(jv.ajax(u + '/favicon.ico,{"timeout":6000}'));
    ok = true;
  } catch (e2) { ok = false; }
  var ms = Date.now() - t0;
  if (ok) {
    try { jv.put('jmHost', u); } catch (e3) {}
    try { jv.put('jmLat' + idx, ms + 'ms'); } catch (e4) {}
    jmToast(jv, '✅ 已切换线路：' + u.replace('https://', '') + '（' + ms + 'ms）');
  } else {
    try { jv.put('jmLat' + idx, '超时'); } catch (e5) {}
    jmToast(jv, '❌ 该线路不可达（超时），未切换');
  }
  try { jv.reLoginView(false); } catch (e6) {}
}

// —— viewName 标签函数（面板每次渲染重跑）——
function jmModeLabel(m) {
  var cur = '';
  try { cur = jmStr(source.get('jmMode')); } catch (e) {}
  if (cur === '') cur = '漫画';
  var icon = m === '漫画' ? '📖' : (m === '小说' ? '📝' : '🎬');
  return icon + ' ' + m + (cur === m ? ' ✓' : '');
}

function jmLineLabel(i) {
  var h = '';
  try { h = jmStr(source.get('jmLine' + i)); } catch (e) {}
  var lat = '';
  try { lat = jmStr(source.get('jmLat' + i)); } catch (e2) {}
  if (h === '') return '线路' + (i + 1) + '（空）';
  var cur = '';
  try { cur = jmStr(source.get('jmHost')); } catch (e3) {}
  var tag = cur === h ? ' ●当前' : '';
  return '切 ' + h.replace('https://', '') + (lat === '' ? '' : ' ' + lat) + tag;
}

function jmHostLabel() {
  var h = '';
  try { h = jmStr(source.get('jmHost')); } catch (e) {}
  if (h === '') h = '默认 abandon.yyc2mhau.cc';
  return '🌐 当前线路：' + h.replace('https://', '');
}

