// jmLib: 线路/模式/请求工具（规则 @js 与 loginUrl 共享；ES5 语法，Rhino 安全子集）
var JM_HOST_DEF = 'https://abandon.yyc2mhau.cc';
var JM_UA = 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.6367.82 Mobile Safari/537.36';
var JM_PUB = 'https://jmtt1.net';

function jmStr(v) {
  var s = String(v == null ? '' : v);
  if (s === 'null' || s === 'undefined') s = '';
  return s;
}

function jmHost(sv) {
  try {
    var h = jmStr(sv.get('jmHost'));
    if (h.indexOf('http') === 0) return h;
  } catch (e1) {}
  try {
    var v = jmStr(sv.getVariable());
    if (v.indexOf('http') === 0) return v;
  } catch (e2) {}
  return JM_HOST_DEF;
}

function jmUA() {
  return JM_UA;
}

function jmOpt(timeout) {
  var t = timeout || 20000;
  return ',{"headers":{"User-Agent":"' + JM_UA + '"},"timeout":' + t + '}';
}

function jmMode(sv) {
  var m = '';
  try {
    m = jmStr(sv.get('jmMode'));
  } catch (e1) {}
  if (m === '') {
    try {
      var v = sv.getVariable();
      m = jmStr(v);
    } catch (e2) {}
  }
  if (m === '小说' || m === '视频') return m;
  return '漫画';
}

