@js:(function(){
var u=String(baseUrl||'');
var t=String(result||'');
var out=[];
// ===== 视频分支 =====
if(u.indexOf('/mv/')>=0){
  var mid=(u.match(/\/detail\/(\d+)/)||[])[1];
  var embed=u.replace(/\/detail\/\d+.*$/,'/embed?id='+ (mid||''));
  var title='';
  try{var mm=String(result).match(/"@type":\s*"VideoObject"[\s\S]{0,2000}?"name":\s*"([^"]+)"/);if(mm)title=mm[1];}catch(e3){}
  try{java.startBrowser(embed, title||'禁漫天堂视频');}catch(e1){}
  out.push('🎬 已在内置浏览器打开播放器。');
  out.push('');
  out.push('若未弹出，点菜单【刷新正文】重试，或手动打开：');
  out.push(embed);
  out.push('');
  out.push('（三层签名链 m3u8+auth_key+1800s 窗口，需浏览器 hls.js 播放）');
  return out.join('\n');
}
// ===== 漫画分支 =====
if(u.indexOf('/comic/')>=0){
  var pi=t.indexOf('<section class="jm-rd-pages"');
  var pe=t.indexOf('</section>',pi);
  var seg=pi>=0?t.substring(pi,pe):t;
  var H=u.match(/^https?:\/\/[^\/]+/);
  H=H?H[0]:'https://abandon.yyc2mhau.cc';
  var re=/data-src="(https?:\/\/[^\/?]+)(\/upload[^"?]+)[^"]*"/g;var m;
  while((m=re.exec(seg))!==null){
    var p=m[2];
    var b=java.base64Encode(p);
    var ext=p.split('.').pop();
    out.push('<img src="'+H+'/social-cover/'+b+'.'+ext+'">');
  }
  if(out.length===0){
    var re2=/<img[^>]*src="https?:\/\/[^\/?]+(\/upload[^"?]+)[^"]*"/g;var m2;
    while((m2=re2.exec(seg))!==null){
      var p2=m2[1];
      var b2=java.base64Encode(p2);
      var e2=p2.split('.').pop();
      out.push('<img src="'+H+'/social-cover/'+b2+'.'+e2+'">');
    }
  }
  return out.join('\n');
}
// ===== 小说分支 =====
var si=t.indexOf('jm-rd-text');
var st=t.indexOf('>',si);
var en=t.indexOf('data-rd-text-end',st);
if(en<0)en=t.indexOf('</article>',st);
if(en<0)en=st+60000;
var seg2=t.substring(st+1,en);
var ps=seg2.match(/<p>[\s\S]*?<\/p>/g)||[];
var ps2=[];
for(var i=0;i<ps.length;i++){
  var x=ps[i].replace(/^<p>/,'').replace(/<\/p>$/,'').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ');
  if(x.replace(/\s/g,'')!=='')ps2.push('　　'+x);
}
if(ps2.length===0){ps2.push(String(t).substring(0,120));}
return ps2.join('\n');
})()

