@js:(function(){
var u=String(baseUrl||'');
var t=String(result||'');
var ps=t.indexOf('data-jm-dt-panel="chap"');
var seg=ps>=0?t.substring(ps):t;
var L=[];
var isC=u.indexOf('/comic/')>=0;
var isV=u.indexOf('/mv/')>=0;
var r;
if(isC){r=/href="(\/comic\/chapter\/\d+\/\d+)"/g;}
else{r=/href="(\/novel_chapter\/\d+\/\d+\.html)"/g;}
var seen={};var m;
while((m=r.exec(seg))!==null){
  var url=m[1];
  if(seen[url])continue;
  seen[url]=1;
  var tail=url.split('/').pop();
  var num=tail.replace(/^\D+/,'').replace(/\.html$/,'');
  var title='\u7b2c'+num+'\u7ae0';
  var ctx=seg.substring(m.index, m.index+600);
  var mn=ctx.match(/jm-dt-ch__no">([^<]+)</);
  var mt=ctx.match(/jm-dt-ch__t">([^<]+)</);
  if(mn&&mt){title=mn[1]+' '+mt[1];}
  var o={};o['title']=title;o['url']=url;L.push(o);
}
try{if(isV){book.type=4;}else if(!isC){book.type=8;}else{book.type=64;}}catch(eT){}
if(L.length===0&&isV){var o2={};o2['title']='\u25b6 \u6253\u5f00\u64ad\u653e';o2['url']=u;L.push(o2);}
return L;
})()

